from pathlib import Path
from docx import Document
from docx.shared import Pt,RGBColor,Twips
from docx.oxml.ns import qn
from layout_helpers import norm
import shutil
R=Path(__file__).resolve().parent;O=R/'candidate'
for f in (R/'source').glob('*.docx'):shutil.copy2(f,O/f.name)
def p(d,t,style=None):d.add_paragraph(t,style)
def h(d,t):p(d,t,'Heading 1')
def new(title,intro):
 d=Document();p(d,title,'Title');p(d,intro);return d
def block(d,title,rows):
 h(d,title);t=d.add_table(rows=0,cols=1)
 for text in rows:t.add_row().cells[0].text=text
def sign(d):
 block(d,'Реквизиты кредитора',['{{НАИМЕНОВАНИЕ_КРЕДИТОРА}}  ИНН {{...}}  ОГРН или ОГРНИП {{...}}\nАдрес {{АДРЕС_КРЕДИТОРА}}  Адрес для корреспонденции {{...}}\nТелефон {{...}}  Электронная почта {{...}}'])
 block(d,'Подпись',['{{ДОЛЖНОСТЬ_ПОДПИСАНТА}}  {{ФИО_ПОДПИСАНТА}}\nОснование полномочий {{...}}\nПодпись __________________  Дата __________________'])
def addresses(d,rows):
 t=d.add_table(rows=0,cols=1)
 for text in rows:t.add_row().cells[0].text=text
 d._body._body.insert(0,t._element)

d=new('Расчёт задолженности для заявления требования','Расчётная форма для ручного заполнения по первичным документам. Автоматических формул нет. Реестр 04 подтверждает наличие документов и хронологию; сумма его строк не переносится в основной долг. Здесь одна работа учитывается один раз, даже если её подтверждают КС-2, КС-3, счёт и акт сверки.')
block(d,'Исходные сведения',['Должник {{...}}  ИНН {{...}}  Дело № {{...}}  Суд {{...}}','Кредитор {{...}}  Договор № {{...}} от {{...}}  Объект {{...}}','Расчёт по состоянию на {{...}}  Подготовил {{...}}  Проверил {{...}}','Дата принятия заявления о банкротстве {{...}}  Процедура {{...}}  Дата введения {{...}}'])
h(d,'Одна карточка на самостоятельную часть работ')
p(d,'Повторяйте карточку по этапам, объёмам или периодам. Связанные документы перечисляйте в одной карточке; не создавайте отдельный долг на каждый подтверждающий документ. Спорную стоимость отмечайте и обосновывайте отдельно.')
block(d,'Карточка работ и расчётов',['Код позиции {{...}}  Работы и период фактического выполнения {{...}}','Дата и основание возникновения обязательства {{...}}  Документы {{...}}','Стоимость учитываемых работ с выбранным порядком НДС {{...}} руб.','Все подтверждения одной суммы {{КС_2_КС_3_СЧЁТ_ПЕРЕПИСКА}}  Строки реестра 04 {{...}}','Платежи, отнесённые на эту позицию {{ДАТА_НОМЕР_НАЗНАЧЕНИЕ_СУММА}}','Из них погашение ранее полученного аванса {{...}} руб.; дополнительная оплата {{...}} руб.','Иные подтверждённые погашения {{ОСНОВАНИЕ_ДОКУМЕНТ_СУММА}}','Остаток = стоимость − погашение аванса − дополнительная оплата − иные погашения {{...}} руб.','Срок оплаты {{...}}  Основание и расчёт срока {{...}}','Квалификация {{РЕЕСТРОВОЕ / ТЕКУЩЕЕ / СПОРНО — ВЫБРАТЬ}}  Мотивировка {{...}}','Статус сдачи и возражения должника {{...}}  Позиция кредитора и доказательства {{...}}'])
d.add_page_break();h(d,'Свод основного долга')
t=d.add_table(rows=1,cols=4)
for c,x in zip(t.rows[0].cells,['Код позиции','Остаток руб.','Категория требования','Основание и документы']):c.text=x
for _ in range(4):
 for c in t.add_row().cells:c.text='{{...}}'
p(d,'Основной долг, заявляемый в реестр {{...}} руб. Текущие требования отдельно {{...}} руб. Спорные по квалификации позиции {{...}} руб. и выбранный порядок предъявления {{...}}. В итог заявления 08 переносите только выбранные реестровые позиции; спорную квалификацию поясните, не включайте одну сумму одновременно в разные итоги.')
h(d,'Санкции рассчитываются отдельно')
block(d,'Карточка санкции',['Код основного требования {{...}}  Вид санкции {{...}}','Основание закона или договора {{...}}  База {{...}} руб.  Ставка {{...}}','Начало периода {{...}}  Конец {{...}}  Причина окончания с нормой и судебным актом {{...}}','Дни, изменение базы при платежах и отдельные интервалы {{...}}','Подробный приложенный расчёт {{...}}  Сумма {{...}} руб.','Проверка совместимости с другими начислениями и исключение повторов {{...}}'])
p(d,'Обычные санкции, мораторные проценты и текущие требования не объединяются без квалификации. Само название платежа не определяет порядок учёта. Сверьте процедуру, дату её введения, основание и предельную дату начисления; состав требования и отдельный учёт санкций проверяйте с учётом статьи 137 Закона № 127-ФЗ. Универсальный расчёт санкций по дату подачи здесь не применяется.')
h(d,'Проверка перед переносом в заявление')
p(d,'Сумма карточек реестрового основного долга {{...}}; отдельно санкции {{...}}; итог заявления {{...}}. Все оплаты распределены один раз {{...}}. Повторные подтверждения исключены {{...}}. НДС единообразен {{...}}. Начисления и даты сверены {{...}}. Суммы совпадают с заявлением 08 и описью 05 {{...}}. Проверил {{ФИО_ДАТА}}.')
d.add_page_break();h(d,'Пример без двойного учёта')
p(d,'Условный этап выполнен до принятия заявления о банкротстве. КС-2 и КС-3 подтверждают одну стоимость 1 000 000 руб. Ранее полученный аванс в части этого этапа погашен на 200 000 руб., дополнительно перечислено 300 000 руб. Других погашений нет. Основной остаток: 1 000 000 − 200 000 − 300 000 = 500 000 руб. Сложение КС-2 и КС-3 дало бы 2 000 000 руб. значений документов, но не увеличило бы стоимость работ.')
p(d,'Другой этап на 400 000 руб. выполнен после принятия заявления. Он рассматривается отдельно по дате и основанию возникновения обязательства: дата договора или подписания КС сама по себе не заменяет анализ исполнения. В примере при подтверждённой квалификации второго этапа как текущего основной долг для заявления в реестр составляет 500 000 руб., а 400 000 руб. предъявляются отдельно в применимом порядке. Санкции в этом примере не рассчитаны.')
p(d,'Сохраните одну карточку на первый этап, перечислив в ней обе формы КС. Во второй карточке укажите другой этап и его квалификацию. Сопоставьте аванс с выписками и распределением погашения, чтобы не вычесть его второй раз из уже уменьшенного остатка. Если часть работ или распределение платежа спорны, приведите расчёт и доказательства своей позиции.')
d.save(O/'10-raschet-zadolzhennosti-i-sostava-trebovaniya.docx')

d=Document();addresses(d,['В Арбитражный суд {{НАИМЕНОВАНИЕ_СУДА}}\nДело № {{НОМЕР_ДЕЛА}}','Кредитор {{НАИМЕНОВАНИЕ_КРЕДИТОРА_ИНН_ОГРН_АДРЕС_КОНТАКТЫ}}','Должник {{НАИМЕНОВАНИЕ_ДОЛЖНИКА_ИНН_ОГРН_АДРЕС}}\nКонкурсный управляющий {{ФИО_АДРЕС}}'])
p(d,'Ходатайство о восстановлении срока заявления требования','Title')
p(d,'Решением Арбитражного суда {{...}} от {{...}} по делу № {{...}} должник признан банкротом и открыто конкурсное производство. Сведения опубликованы {{ОФИЦИАЛЬНЫЙ_ИСТОЧНИК_НОМЕР_ДАТА_ССЫЛКА}}. Срок закрытия реестра с учётом правил исчисления истёк {{ДАТА}}; расчёт срока {{...}}.')
p(d,'Кредитор предъявляет требование {{ОСНОВАНИЕ}} в размере {{...}} руб. основного долга и {{...}} руб. санкций. Заявление об установлении требования {{ПОДАЁТСЯ_ОДНОВРЕМЕННО / ПОДАНО_ДАТА_ПОДТВЕРЖДЕНИЕ}}. Пропуск срока обусловлен следующими обстоятельствами.')
h(d,'Обстоятельства и доказательства')
p(d,'{{ОПИШИТЕ_КОНКРЕТНОЕ_ПРЕПЯТСТВИЕ}}, действовавшее с {{ДАТА}} по {{ДАТА}}, препятствовало своевременному предъявлению требования, поскольку {{ПРИЧИННАЯ_СВЯЗЬ}}. Подтверждающие документы {{...}}. При наличии иных причин приведите их отдельно с периодами и доказательствами.')
p(d,'Обстоятельства, необходимые для предъявления требования, {{УКАЖИТЕ_ЕСЛИ_ПРИМЕНИМО}} наступили {{ДАТА}}, что подтверждается {{...}}. О возможности предъявления требования кредитору стало известно {{ДАТА_И_ОБСТОЯТЕЛЬСТВА}}. До этого предприняты действия {{...}}. После устранения препятствия кредитор {{ХРОНОЛОГИЯ_ДЕЙСТВИЙ_И_ДАТЫ}}. Период до подачи объясняется {{...}}.')
p(d,'Считаем причины уважительными по следующим основаниям {{МОТИВИРОВКА_ПРИМЕНИТЕЛЬНО_К_ДОКУМЕНТАМ}}. На основании абзаца третьего пункта 1 статьи 142 Федерального закона № 127-ФЗ прошу восстановить срок заявления требования кредитора и признать требование, изложенное в заявлении от {{...}}, заявленным в срок.')
p(d,'Приложения: 1. Судебный акт и официальная публикация. 2. Расчёт срока. 3. Хронология препятствия и доказательства по каждой причине {{...}}. 4. Заявление требования либо подтверждение его подачи. 5. Полномочия подписанта. 6. Подтверждения направления участникам по применимому порядку {{...}}.')
sign(d);d.save(O/'11-hodataystvo-o-vosstanovlenii-sroka.docx')

for code in ['06','07','08']:
 f=next(O.glob(code+'*.docx'));d=Document(f)
 for t in list(d.tables):
  if 'Подпись' in ''.join(c.text for row in t.rows for c in row.cells):t._element.getparent().remove(t._element)
 for para in list(d.paragraphs):
  if para.text=='Кредитор' or para.text.startswith(('Должность {{','Подпись ___')):para._element.getparent().remove(para._element)
 header=[]
 for para in list(d.paragraphs):
  if para.text.startswith(('Арбитражному управляющему','От кредитора','Должник ','В Арбитражный суд','Дело №','Должник:','Кредитор:','Арбитражный управляющий:')):
   header.append(para.text);para._element.getparent().remove(para._element)
 if header:addresses(d,header)
 if code=='08':
  p(d,'Расчёт основного долга и состава требования составлен отдельно по форме 10; одинаковые работы, подтверждённые несколькими документами, учтены один раз. Заявленная сумма сверена с описью и первичными документами {{РЕКВИЗИТЫ_РАСЧЁТА}}.')
 sign(d);d.save(f)
for code in ['01','02','05','09']:
 f=next(O.glob(code+'*.docx'));d=Document(f)
 h(d,'Связь расчёта с заявлением')
 p(d,'Реестр 04 — опись и хронология, а не калькулятор долга. Основной долг, оплаты, погашение аванса и самостоятельные периоды работ сведите в расчёт 10. Его реестровую часть и отдельно санкции сверяйте с заявлением 08 и описью 05. Автоматических формул в расчёте 10 нет. При пропуске срока в конкурсном производстве используйте форму 11 после проверки причин; удовлетворение ходатайства решает суд.')
 if code=='09':p(d,'Форма 11 предназначена для срока закрытия реестра в конкурсном производстве по статье 142. Не переносите её автоматически на 30-дневный срок наблюдения или специальные категории требований. Само отсутствие сведений о банкротстве либо ожидание ответа управляющего не означает подтверждённой уважительности причины.')
 d.save(f)
for f in O.glob('*.docx'):
 d=Document(f);norm(d)
 for sec in d.sections:sec.top_margin=Twips(850);sec.bottom_margin=Twips(850)
 for s in d.styles:
  if s.type==1:
   s.font.name='Arial';s.font.color.rgb=RGBColor(0,0,0);s.font.size=Pt(10 if s.name=='Normal' else 16 if s.name=='Title' else 11)
   s.paragraph_format.space_after=Pt(6)
   if s._element.pPr is not None:
    for x in list(s._element.pPr.findall(qn('w:pBdr'))):s._element.pPr.remove(x)
 for para in d.paragraphs:
  if 'редакцию 21.10.2026' in para.text:para.text=para.text.replace('21.10.2026','30.10.2026')
  if para.text.startswith(('УВЕДОМЛЕНИЕ О','ЗАПРОС О','ЗАЯВЛЕНИЕ ОБ')):
   para.style='Title'
   for run in para.runs:run.font.size=Pt(13)
 for c in d._element.iter(qn('w:color')):c.attrib.clear();c.set(qn('w:val'),'000000')
 for sec in d.sections:
  for para in sec.footer.paragraphs:
   if '21.10.2026' in para.text:para.text=para.text.replace('21.10.2026','30.10.2026')
   for run in para.runs:run.font.color.rgb=RGBColor(0,0,0)
 if f.name.startswith('05'):
  for table in d.tables:
   if len(table.columns)==4:
    widths=[4800,2300,1500,1266]
    for col,width in zip(table.columns,widths):col.width=Twips(width)
    for row in table.rows:
     for cell,width in zip(row.cells,widths):cell.width=Twips(width)
 d.save(f)
print('Built 10 DOCX')
